25	/// Sort a chunk of `ImportDeclaration`s and replace the original `FormatElement`s with the sorted ones
26	/// in the formatter buffer.
27	///
28	/// `chunk_start` is the buffer position of the start of the chunk.
29	/// i.e. the buffer position recorded just before the first `entry` call for first `ImportDeclaration` in the chunk.
30	///
31	/// The chunk buffer must contain nothing but the `FormatElement`s generated from `ImportDeclaration`s,
32	/// and their preceding/trailing comments, and line breaks.
33	///
34	/// The chunk slice does not include any trailing line break, and `transform` produces a slice with
35	/// the same shape. The inter-statement separator is written by the next `entry` call
36	/// (or the closing newline emitted by `Program::write`).
37	///
38	/// The caller must already have verified that `sort_imports` option is enabled.
39	///
40	/// # Panics
41	/// Panics if `sort_imports` option is not enabled.
42	pub fn sort_imports_chunk(formatter: &mut Formatter<'_, '_>, chunk_start: usize) {
43	    let elements = &formatter.elements()[chunk_start..];
44	    let options = formatter.options().sort_imports.as_ref().unwrap();
45	
46	    let sorted_elements = transform(elements, options, formatter.allocator());
47	    formatter.replace_end(chunk_start, &sorted_elements);
48	}
