20	impl<'a> FormatWrite<'a> for AstNode<'a, Program<'a>> {
21	    fn write(&self, f: &mut Formatter<'_, 'a>) {
22	        let format_trailing_comments = format_with(|f| {
23	            write!(
24	                f,
25	                FormatTrailingComments::Comments(f.context().comments().unprinted_comments())
26	            );
27	        });
28	
29	        write!(
30	            f,
31	            [
32	                // BOM
33	                f.source_text()
34	                    .chars()
35	                    .next()
36	                    .is_some_and(|c| c == ZWNBSP)
37	                    .then_some(text("\u{feff}")),
38	                self.hashbang(),
39	                self.directives(),
40	                FormatStatementsWithImports(self.body()),
41	                format_trailing_comments,
42	                hard_line_break()
43	            ]
44	        );
45	    }
46	}
