57	impl<'a> Format<'a> for FormatStatementsWithImports<'a, '_> {
58	    fn fmt(&self, f: &mut Formatter<'_, 'a>) {
59	        let import_sort_enabled = f.options().sort_imports.is_some();
60	
61	        let mut join = f.join_nodes_with_hardline();
62	
63	        let mut stmts_iter =
64	            self.iter().filter(|stmt| !matches!(stmt.as_ref(), Statement::EmptyStatement(_)));
65	        while let Some(mut stmt) = stmts_iter.next() {
66	            // Suppressed imports are emitted verbatim and act as partition boundaries,
67	            // so they are excluded from the sortable run.
68	            if import_sort_enabled
69	                && matches!(stmt.as_ref(), Statement::ImportDeclaration(_))
70	                && !is_import_suppressed(stmt, join.fmt())
71	            {
72	                let next_stmt = format_import_decls_with_sort(stmt, &mut stmts_iter, &mut join);
73	                match next_stmt {
74	                    Some(next_stmt) => stmt = next_stmt,
75	                    None => break,
76	                }
77	            }
78	
79	            let span = match stmt.as_ref() {
80	                // `@decorator export class A {}`
81	                // Get the span of the decorator.
82	                Statement::ExportNamedDeclaration(export) => {
83	                    if let Some(Declaration::ClassDeclaration(decl)) = &export.declaration
84	                        && let Some(decorator) = decl.decorators.first()
85	                        && decorator.span().start < export.span.start
86	                    {
87	                        decorator.span()
88	                    } else {
89	                        export.span
90	                    }
91	                }
92	                // `@decorator export default class A {}`
93	                // Get the span of the decorator.
94	                Statement::ExportDefaultDeclaration(export) => {
95	                    if let ExportDefaultDeclarationKind::ClassDeclaration(decl) =
96	                        &export.declaration
97	                        && let Some(decorator) = decl.decorators.first()
98	                        && decorator.span().start < export.span.start
99	                    {
100	                        decorator.span()
101	                    } else {
102	                        export.span
103	                    }
104	                }
105	                _ => stmt.span(),
106	            };
107	
108	            join.entry(span, stmt);
109	        }
110	    }
111	}
