167	/// An `ImportDeclaration` is suppressed if it has a leading or trailing suppression comment,
168	/// which causes it to be emitted verbatim and act as a partition boundary, excluding it from the sortable run.
169	fn is_import_suppressed(stmt: &AstNode<'_, Statement<'_>>, f: &Formatter<'_, '_>) -> bool {
170	    let span = stmt.span();
171	    let comments = f.comments();
172	    comments.is_suppressed(span.start) || comments.has_trailing_suppression_comment(span.end)
173	}
