63	    #[inline]
64	    pub fn format_with_external_callbacks(
65	        self,
66	        program: &'a Program<'a>,
67	        external_callbacks: Option<ExternalCallbacks>,
68	    ) -> Formatted<'a> {
69	        let program_node = AstNode::new(program, AstNodes::Dummy(), self.allocator);
70	
71	        let context = FormatContext::new(
72	            program.source_text,
73	            program.source_type,
74	            &program.comments,
75	            self.allocator,
76	            self.options,
77	            external_callbacks,
78	        );
79	
80	        formatter::format(
81	            context,
82	            formatter::Arguments::new(&[formatter::Argument::new(&program_node)]),
83	        )
84	    }
