    let trailing = "import z from \"z\";\nimport a from \"a\";\n// trailing comment\nconst x = 1;\n";

    run("single-jsdoc+sort", single, true, true);
    run("multi-jsdoc+sort", multi, true, true);
    run("trailing-sort-only", trailing, false, true);
}
