}", "newString": "impl<'a> Format<'a> for FormattedJsdoc<'a> {
    fn fmt(&self, f: &mut Formatter<'_, 'a>) {
        // When import sorting is enabled, wrap the emitted comment IR in the
        // `AlignableBlockComment` label, exactly as the non-JSDoc block-comment path does
        // (see `Comment::fmt` in `trivia.rs`). The JSDoc formatter emits its content as
        // `token()`/`text()` elements (and, for multi-line comments, internal
        // `hard_line_break()`s). Without the label, the import-sort IR transform splits at
        // those hard breaks and tries to interpret the resulting comment fragments (e.g.
        // `/**`) as import lines, which panics. The label tells the transform to treat the
        // whole comment as a single unit. The `Empty` case emits nothing, so it needs no label.
        let label_alignable = !matches!(self, FormattedJsdoc::Empty)
            && f.options().sort_imports.is_some();
        if label_alignable {
            f.write_element(FormatElement::Tag(Tag::StartLabelled(LabelId::of(
                JsLabels::AlignableBlockComment,
            ))));
        }

        match self {
            FormattedJsdoc::Empty => {}
            FormattedJsdoc::SingleLine(content) => {
                write!(f, [token("/**"), " ", text(content), " ", token("*/")]);
            }
            FormattedJsdoc::MultiLine(content_str) => {
                write!(f, [token("/**")]);
                for line in content_str.split('\n') {
                    if line.is_empty() {
                        write!(f, [hard_line_break(), " ", token("*")]);
                    } else {
                        write!(f, [hard_line_break(), " ", token("*"), " ", text(line)]);
                    }
                }
                write!(f, [hard_line_break(), " ", token("*/")]);
            }
        }

        if label_alignable {
            f.write_element(FormatElement::Tag(Tag::EndLabelled));
        }
    }
